export const LOCAL_TRB_INSTANCES_VERSION = "0.6.5j-local-geometry-instances";
const GEOMETRY_INSTANCE_SIZE = 20;
function check(o,s,t,l){if(!Number.isInteger(o)||o<0||o+s>t)throw new RangeError(`${l}: ${o}+${s}>${t}`)}
function u8(v,o){check(o,1,v.byteLength,"u8");return v.getUint8(o)}
function u16(v,o){check(o,2,v.byteLength,"u16");return v.getUint16(o,true)}
function u32(v,o){check(o,4,v.byteLength,"u32");return v.getUint32(o,true)}
function i32(v,o){check(o,4,v.byteLength,"i32");return v.getInt32(o,true)}
function table(v,o,l){check(o,4,v.byteLength,l);const vt=o-i32(v,o);check(vt,4,v.byteLength,`${l}.vtable`);const vl=u16(v,vt),ol=u16(v,vt+2);if(vl<4||vl>1024||ol<4||ol>4096)throw new Error(`${l}: invalid table`);return{tableOffset:o,vtableOffset:vt,fieldCount:(vl-4)/2}}
function address(v,t,i){const s=t.vtableOffset+4+i*2;if(s+2>t.vtableOffset+4+t.fieldCount*2)return null;const r=u16(v,s);return r?t.tableOffset+r:null}
function child(v,t,i,l){const a=address(v,t,i);return a==null?null:table(v,a+u32(v,a),l)}
function vector(v,t,i,l){const a=address(v,t,i);if(a==null)return null;const x=a+u32(v,a);return{label:l,targetOffset:x,dataOffset:x+4,length:u32(v,x)}}
function safeVector(v,t,i,l){try{return vector(v,t,i,l)}catch{return null}}
function histogram(values){const m=new Map();for(const x of values)m.set(x,(m.get(x)||0)+1);return Array.from(m,([value,count])=>({value,count})).sort((a,b)=>a.value-b.value)}
function poolLengths(v,g){const fields=[];for(let i=0;i<g.fieldCount;i++){const x=safeVector(v,g,i,`geometry.${i}`);fields.push({fieldIndex:i,length:x?.length??0,dataOffset:x?.dataOffset??null})}return fields}
function decodeInstances(v,vec){const records=[];for(let i=0;i<vec.length;i++){const o=vec.dataOffset+i*GEOMETRY_INSTANCE_SIZE;check(o,GEOMETRY_INSTANCE_SIZE,v.byteLength,"GeometryInstance");records.push({instanceIndex:i,raw0:u32(v,o),raw1:u32(v,o+4),raw2:u32(v,o+8),raw3:u32(v,o+12),raw4:u32(v,o+16)})}return records}
export class TrimBimGeometryInstancesReader{
 static open(buffer){return new TrimBimGeometryInstancesReader(buffer)}
 constructor(buffer){this.view=new DataView(buffer);this.bytes=new Uint8Array(buffer);this.root=table(this.view,u32(this.view,0),"root");this.header={identifier:String.fromCharCode(...this.bytes.slice(4,8)),byteLength:buffer.byteLength}}
 diagnostic(){const v=this.view,e=child(v,this.root,0,"ModelEntities"),g=child(v,this.root,2,"ModelGeometry"),entities=vector(v,e,0,"entities"),instances=vector(v,g,4,"instances"),records=decodeInstances(v,instances),fields=poolLengths(v,g);const columns=[0,1,2,3,4].map(i=>{const vals=records.map(r=>r[`raw${i}`]);return{field:`raw${i}`,minimum:Math.min(...vals),maximum:Math.max(...vals),histogram:histogram(vals),sample:vals.slice(0,40)}});const pools=[
  {fieldIndex:5,name:"textures"},{fieldIndex:6,name:"bReps"},{fieldIndex:7,name:"triangleMeshes"},{fieldIndex:8,name:"triangleMeshes8"},{fieldIndex:9,name:"texturedTriangleMeshes"},{fieldIndex:10,name:"texturedTriangleMeshes8"},{fieldIndex:11,name:"sweptDiskSolids"},{fieldIndex:12,name:"bRepWithUvs"},{fieldIndex:13,name:"bRepWithNormals"},{fieldIndex:14,name:"graphicsContainers"},{fieldIndex:15,name:"alignmentCurves"},{fieldIndex:16,name:"gridLineContainers"},{fieldIndex:17,name:"coordinateGeometryPoints"},{fieldIndex:18,name:"billboardTexts"},{fieldIndex:19,name:"textStyles"},{fieldIndex:20,name:"billboards"},{fieldIndex:21,name:"texturedBillboards"},{fieldIndex:22,name:"bolts"},{fieldIndex:23,name:"layerDefaultVisibility"}
 ].map(x=>({...x,length:fields.find(f=>f.fieldIndex===x.fieldIndex)?.length??0}));return{readerVersion:LOCAL_TRB_INSTANCES_VERSION,header:this.header,schema:{geometryInstancesFieldIndex:4,geometryInstanceSizeBytes:GEOMETRY_INSTANCE_SIZE},counts:{entityCount:entities.length,instanceCount:instances.length,instancesPerEntity:instances.length/entities.length},instances:{records:records.slice(0,60),columns,recordCount:records.length},geometryPools:pools,validation:{instanceVectorByteSpan:instances.length*GEOMETRY_INSTANCE_SIZE,nextPoolDistance:(safeVector(v,g,3,"previous")?.dataOffset??instances.dataOffset)-instances.dataOffset,recordsDecoded:true,semanticFieldNamesDecoded:false,transformsDecoded:false,meshArraysDecoded:false},note:"All 182 GeometryInstance structs are decoded as five raw uint32 fields using verified SIZE=20. Semantic names remain intentionally withheld until each column is validated against pool lengths and entity references."}}
}
